def index_by(items: Iterable[T], key: Callable[[T], K]) -> dict[K, T]:
    """Map key(item) -> item. Raises ValueError on a repeated key instead of silently overwriting."""
    out: dict[K, T] = {}
    for item in items:
        k = key(item)
        if k in out:
            raise ValueError(f"duplicate key {k!r}")
        out[k] = item
    return out

